import{_ as l,o as e,c as t,a5 as n}from"./chunks/framework.DJo0M80U.js";const b=JSON.parse('{"title":"runnable 和 callable 有什么区别","description":"","frontmatter":{"title":"runnable 和 callable 有什么区别","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","核心API","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第三部分：核心 API/07-异常与线程/线程和进程区别/runnable 和 callable 有什么区别.md","filePath":"posts/java快速入门/第三部分：核心 API/07-异常与线程/线程和进程区别/runnable 和 callable 有什么区别.md"}'),r={name:"posts/java快速入门/第三部分：核心 API/07-异常与线程/线程和进程区别/runnable 和 callable 有什么区别.md"};function s(_,a,i,u,c,o){return e(),t("div",null,[...a[0]||(a[0]=[n("<div><p>说一下 runnable 和 callable 有什么区别 相同点：</p><ul><li>都是接口</li><li>都可以编写多线程程序</li><li>都采用Thread.start()启动线程</li></ul><p>主要区别：</p><ul><li>Runnable 接口 run 方法无返回值；</li><li>Callable 接口 call 方法有返回值，是个泛型，和Future、FutureTask配合可以用来获取异步执行的结果</li><li>Runnable 接口 run 方法只能抛出运行时异常，且无法捕获处理；</li><li>Callable 接口 call 方法允许抛出异常，可以获取异常信息</li></ul><p>注：Callalbe接口支持返回执行结果，需要调用FutureTask.get()得到，此方法会阻塞主进程的继续往下执行，如果不调用不会阻塞。</p></div>",1)])])}const d=l(r,[["render",s]]);export{b as __pageData,d as default};
